                                            {{#each ../../product.custom_fields}}
                                                {{#if name '==' 'custom_bike_4_image'}}{{value}}{{/if}}
                                            {{/each}}
                                         "
                                         alt="{{value}}">
                                </div>
                                <div class="blog-details">
                                    <h3 class="blog-title">{{value}}</h3>
                                    <p class="price">
                                        {{#each ../../product.custom_fields}}
                                            {{#if name '==' 'custom_bike_4_price'}}{{value}}{{/if}}
                                        {{/each}}
                                    </p>
                                    <span class="shop-button">Shop</span>
                                </div>
                            </a>
                        </div>
                    </div>
                {{/if}}
            {{/each}}
        </div>
    </div>
</section>
    {{/if}}
{{/each}}
